def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())
    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = lines[1 + i].split()
        if len(parts) != 3:
            continue
        a, b, e = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((a - 1, b - 1, e, i))

    edges_sorted = sorted(edges, key=lambda x: x[2])

    parent = list(range(n))
    def find(x):
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_indices = set()
    for a, b, e, idx in edges_sorted:
        if union(a, b):
            mst_indices.add(idx)

    # Build MST adjacency list
    adj = [[] for _ in range(n)]
    for a, b, e, idx in edges:
        if idx in mst_indices:
            adj[a].append((b, e))
            adj[b].append((a, e))

    # BFS to find depths, parents, and max edge to root
    depth = [-1] * n
    parent = [0] * n
    max_edge_to_root = [0] * n
    head = [0] * n  # to track position in DFS order

    depth[0] = 0
    queue = [(0, 0)]  # node, depth
    visited = [False] * n
    visited[0] = True

    dfs_order = []
    parent_node = [0] * n

    idx = 0
    while idx < len(queue):
        u, d = queue[idx]
        idx += 1
        dfs_order.append(u)
        parent_node[u] = parent[u]

        for v, e in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = d + 1
                parent[v] = u
                max_edge_to_root[v] = max(e, max_edge_to_root[u]) if u != 0 else e
                queue.append((v, d + 1))

    # Maximum edges on path for each node and power of 2 up
    LOG = n.bit_length()
    max_up = [[0] * LOG for _ in range(n)]
    for i in range(n):
        max_up[i][0] = max_edge_to_root[i]
        depth_for_lca = depth[i]
        p_i = parent[i]

        # If node is not 0, it has an edge to parent
        if i != 0:
            max_up[i][0] = max_edge_to_root[i]
        else:
            max_up[i][0] = 0

        for j in range(1, LOG):
            if p_i >= 0:
                max_up[i][j] = max(max_up[i][j-1], max_up[p_i][j-1])
            else:
                max_up[i][j] = 0

    def get_max_on_path(a, b):
        if depth[a] < depth[b]:
            a, b = b, a

        ans = 0

        for j in range(LOG - 1, -1, -1):
            if depth[a] - (1 << j) >= depth[b]:
                ans = max(ans, max_up[a][j])
                a = parent[a]

            if a != parent[b]:
                ans = max(ans, max_up[b][j])
                b = parent[b]

        if a != b:
            ans = max(ans, max_up[a][0])
            ans = max(ans, max_up[b][0])
            return ans
        return ans

    adj_map = {}
    for i, (a, b, e, idx) in enumerate(edges):
        adj_map[idx] = e

    # Return answers for edges not in MST, outputting the max weight as E_max
    # E_max for edge (u,v) with weight w is the max weight on MST path between u and v

    output_lines = []
    for a, b, e, idx in edges:
        if idx not in mst_indices:
            max_on_path = get_max_on_path(a, b)
            output_lines.append(str(max_on_path))

    return '\n'.join(output_lines)
