    def union(i, j):
        ri, rj = find(i), find(j)
        if ri != rj:
            parent[ri] = rj
            return True
        return False

    selected = []
    capital_count = 0

    for w, a, b, idx in edges:
        if union(a, b):
            selected.append(idx)
            if a == 1 or b == 1:
                capital_count += 1

    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return "-1\n"

    return f"{len(selected)}\n" + " ".join(map(str, sorted(selected))) + "\n"
