def solution(input_str):
    """
    Count trailing zeros in n! by using Legendre's formula.
    Trailing zeros = sum of floor(n/(2^k)) for k >= 1
    """
    n = int(input_str.strip())

    if n == 0:
        return "0"

    result = 0
    power_of_2 = 2
    while power_of_2 <= n:
        result += n // power_of_2
        power_of_2 *= 2

    return str(result)
