    xp, yp, vp = map(int, lines[0].split())
    x, y, v, r = map(int, lines[1].split())

    R = math.sqrt(xp*xp + yp*yp)
    planet_omega = vp / R

    start_dist = math.sqrt(x*x + y*y)
    start_angle = math.atan2(y, x)
    planet_angle = math.atan2(yp, xp)

    # Handle zero distance case
    if start_dist < r:
        # Need to go outward first
        time_out = (r - start_dist) / v if r > start_dist else 0
    else:
        time_out = 0

    # Binary search for minimum interception time
    lo, hi = 0.0, 2000.0  # Sufficient upper bound

    for _ in range(100):  # 100 iterations for high precision
        mid = (lo + hi) / 2.0

        # Planet's position at time mid
        px = R * math.cos(planet_angle + planet_omega * mid)
        py = R * math.sin(planet_angle + planet_omega * mid)

        # Distance to planet at intercept time
        dist_to_planet = math.sqrt((x - px)**2 + **(y - py)2)

        # Check if path stays safe
        if mid <= time_out:
            if dist_to_planet >= r - 1e-9:
                hi = mid
            else:
                lo = mid
        else:
            # Additional time spent at radius r or more
            hi = mid

    return f'{hi:.10f}\n'
