from collections import Counter
import sys

def solution(input_data):
    data = input_data.strip('\n').split('\n')
    n, m = map(int, data[0].split())
    matrix = [list(row) for row in data[1:]]

    ord_a = ord('a')

    # 2D prefix sum per character
    pre = [[[0] * m for _ in range(n + 1)] for _ in range(26)]

    for char_idx in range(26):
        for r in range(1, n + 1):
            for c in range(1, m + 1):
                val = 1 if matrix[r - 1][c - 1] == chr(ord_a + char_idx) else 0
                prefix = (pre[char_idx][r][c - 1] if c > 0 else 0) + \
                         (pre[char_idx][r - 1][c] if r > 0 else 0) - \
                         (pre[char_idx][r - 1][c - 1] if r > 0 and c > 0 else 0)
                pre[char_idx][r][c] = prefix + val

    def count_char(char_idx, r1, c1, r2, c2):
        r1, c1, r2, c2 = r1 + 1, c1 + 1, r2 + 1, c2 + 1
        return pre[char_idx][r2][c2] - pre[char_idx][r1 - 1][c2] - pre[char_idx][r2][c1 - 1] + pre[char_idx][r1 - 1][c1 - 1]

    ans = 0
    for r1 in range(n):
        for r2 in range(r1, n):
            for c1 in range(m):
                for c2 in range(c1, m):
                    rows_ok = True
                    for r in range(r1, r2 + 1):
                        odd = sum(count_char(char_idx, r, c1, r, c2) % 2 for char_idx in range(26))
                        if odd > 1:
                            rows_ok = False
