    n, m = map(int, lines[0].split())
    total_nodes = 2 * m

    # Build implication graph
    graph = [[] for _ in range(total_nodes)]
    rev_graph = [[] for _ in range(total_nodes)]

    def get_node(x, neg):
        """Convert literal to node. x is 1-indexed variable, neg is boolean for negated."""
        return (x - 1) + (m if neg else 0)

    def neg_node(node):
        """Get the node representing the negation."""
        return node ^ (m - 1)

    # Parse clauses and build the implication graph
    # For clause (lit1 ∨ lit2 ∨ ... ∨ litk), we add implications:
    #   ¬lit1 → lit2, ¬lit1 → lit3, ..., ¬lit1 → litk
    #   ¬lit2 → lit1, ¬lit2 → lit3, ..., ¬lit2 → litk
    #   ... and so on
    # Actually for CNF, we only need: ¬lit1 → lit2 OR lit3 OR ... (which simplifies)
    # For 2-SAT, if clause is A ∨ B ∨ C, then ¬A → B and ¬A → C, etc.

    for i in range(1, n + 1):
        parts = lines[i].split()
        k = int(parts[0])
        literals = [int(x) for x in parts[1:]]

        for idx in range(k):
            for other in range(k):
                if idx != other:
                    lit_i_node = get_node(literals[idx], literals[idx] < 0)
                    lit_j_node = get_node(literals[other], literals[other] < 0)

                    # If literal i is false, then literal j must be true
                    source = neg_node(lit_i_node)
                    if source >= 0 and source < total_nodes:
                        graph[source].append(lit_j_node)
                        rev_graph[lit_j_node].append(source)

    # Kosaraju's algorithm for finding strongly connected components
    # Pass 1: DFS on original graph, store nodes in order of finishing
    visited = [False] * total_nodes
    order = []

    # Use iterative DFS to avoid recursion issues
    for i in range(total_nodes):
        if not visited[i]:
            work_stack = [(i, 0)]  # (node, iteration_index)
            while work_stack:
                node, idx = work_stack[-1]
                if idx == 0:
                    visited[node] = True

