        while stack:
            node = stack[-1]
            visited[node] = True
            # Keep track of next neighbor to process
            visited_edges[node].append(stack.pop())

    # First pass complete
    visited = [False] * total_nodes
    order = []

    stack = [(i, 0) for i in range(total_nodes)]

    for i in range(total_nodes):
        if not visited[i]:
            work_stack = [i]
            while work_stack:
                node = work_stack.pop()
                if visited[node]:
                    continue
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        work_stack.append(neighbor)
                order.append(node)

    # Pass 2: DFS on reverse graph in reverse order
    visited = [False] * total_nodes
    comp = [-1] * total_nodes
    comp_count = 0

    for i in range(len(order) - 1, -1, -1):
        node = order[i]
        if not visited[node]:
            # Start new component
            stack = [node]
            visited[node] = True
            comp[node] = comp_count

            while stack:
                curr = stack.pop()

                for neighbor in rev_graph[curr]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        comp[neighbor] = comp_count
                        stack.append(neighbor)

            comp_count += 1

    # Check satisfiability
    for i in range(m):
        pos = get_node(i + 1, False)
        neg = get_node(i + 1, True)
        if comp[pos] == comp[neg]:
            return "NO"

    # Build the satisfying assignment
    result = [0] * m
    for i in range(m):
        pos = get_node(i + 1, False)
        neg = get_node(i + 1, True)
        # In topological order, assign True to the earlier component
        if comp[pos] < comp[neg]:
            result[i] = 1
        else:
            result[i] = 0

    return "YES\n" + "".join(map(str, result))
