        parts = lines[i].split()
        rules.append((int(parts[0]), parts[1], int(parts[2]), parts[3]))

    s = lines[2 + m].strip() if len(lines) > 2 + m else ""

    def char_vowel(c):
        try:
            idx = list('abcdefghijklmnopqrstuvwxyz').index(c)
        except:
            return 'X'
        return vocab[idx]

    def full_valid(w):
        for p1, t1, p2, t2 in rules:
            if char_vowel(w[p1-1]) == t1:
                if char_vowel(w[p2-1]) != t2:
                    return False
        return True

    def try_fill(idx, w):
        if idx == n:
            return w if full_valid(w) else ""

        for c in range(ord('a'), ord('a') + len(vocab)):
            w[idx] = chr(c)
            result = try_fill(idx + 1, w)
            if result:
                return result
        return ""

    target = list(s)
    if full_valid(target):
        return s

    for i in range(n - 1, -1, -1):
        original = target[i]
        for c_code in range(ord(s[i]) + 1, ord('a') + len(vocab)):
            target[i] = chr(c_code)
            temp = target[:] + [''] * (n - len(target))
            res = try_fill(i + 1, temp)
            if res:
                return "".join(target[:i+1]) + "".join(res)
        target[i] = s[i]

    return "-1"
