```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    q = int(lines[0])
    k_list = []
    for i in range(1, q + 1):
        k_list.append(int(lines[i]))

    # Precompute cumulative digits for powers of 10 minus 1: P9[i] = digits in 1..(10^i-1)
    P9 = [0] * 19
    for i in range(1, 19):
        P9[i] = P9[i-1] + 9 * (10 ** (i-1)) * i

    def count_digits_upto(n):
        """Count total digits in numbers 1 to n"""
        if n <= 0:
            return 0
        d = int(math.log10(n))
        result = P9[d] + (n - (10 ** d) + 1) * (d + 1)
        return result

    def total_block_length(n):
        """Total digits in block n = digits in numbers 1 to n"""
        return count_digits_upto(n)

    def cum_block_len(n):
        """Cumulative length of all blocks from 1 to n"""
        cum = 0
        for i in range(1, n + 1):
            cum += total_block_length(i)
        return cum

    def find_kth_digit(k):
        """Find the digit at position k (1-indexed)"""
        # Binary search to find which block contains position k
        left, right, best = 1, 2 * 10**18, k
        position = k

        while left <= right:
            mid = (left + right) // 2
            if mid < 1 or cum_block_len(mid) < k:
                left = mid + 1
            elif cum_block_len(mid) >= k:
                best = mid
                position = k - cum_block_len(best - 1)
                right = mid - 1

        block = best
        pos_in_block = position

        # Find which number in the block (1 to block)
        num = 1
        digits_found = 0

        while True:
            num_len = len(str(num))
            if digits_found + num_len >= pos_in_block:
                digit_idx = pos_in_block - digits_found - 1
                return str(num)[digit_idx]
            digits_found += num_len
            num += 1

    results = []
    for k in k_list:
        digit = find_kth_digit(k)
        results.append(digit)

    return '\n'.join(results)
