def solution(input_str):
    """
    Find the longest common subsequence of s1 and s2 that doesn't contain virus as substring.
    """
    lines = input_str.strip().split('\n')
    s1 = lines[0]
    s2 = lines[1]
    virus = lines[2]

    n1, n2, n3 = len(s1), len(s2), len(virus)

    if n3 == 0:
        # No virus constraint - standard LCS
        dp = [[""] * (n2 + 1) for _ in range(n1 + 1)]
        for i in range(n1):
            for j in range(n2):
                if s1[i] == s2[j]:
                    if dp[i][j]:
                        dp[i + 1][j + 1] = dp[i][j] + s1[i]
                dp[i + 1][j + 1] = max([dp[i + 1][j + 1], dp[i][j + 1], dp[i + 1][j]], key=len)
        result = dp[n1][n2]
        return "0" if result == "" else result

    # KMP prefix function (failure function) for virus
    pi = [0] * n3
    for i in range(1, n3):
        j = pi[i - 1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j - 1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    def next_state(k, c):
        """Calculate KMP state after adding character c when currently at state k"""
        while k > 0 and virus[k] != c:
            k = pi[k - 1]
        if k < n3 and virus[k] == c:
            k += 1
        return k

    INF = -float('inf')
    dp = [[[INF] * n3 for _ in range(n2 + 1)] for _ in range(n1 + 1)]

    # Initial state: both strings processed, virus state 0
    for k in range(n3):
        dp[0][0][k] = 0
    dp[0][0][0] = 0

    for i in range(n1 + 1):
        for j in range(n2 + 1):
            for k in range(n3):
                if dp[i][j][k] <= INF:
                    # Try advancing in s1
                    if i < n1:
                        nk = next_state(k, s1[i])
                        if nk < n3:
                            dp[i + 1][j][nk] = max(dp[i + 1][j][nk], dp[i][j][k])

                    # Try advancing in s2
                    if j < n2:
                        nk = next_state(k, s2[j])
                        if nk < n3:
                            dp[i][j + 1][nk] = max(dp[i][j + 1][nk], dp[i][j][k])

                    # Try matching s1's char with s2's char
                    if i < n1 and j < n2 and s1[i] == s2[j]:
                        nk = next_state(k, s1[i])
                        if nk < n3:
                            dp[i + 1][j + 1][nk] = max(dp[i + 1][j + 1][nk], dp[i][j][k] + 1)

    # Find maximum value in the final row
    max_len = 0
    for k in range(n3):
        if dp[n1][n2][k] > max_len:
            max_len = dp[n1][n2][k]

    if max_len == 0:
        return "0"

    # Reconstruct the solution
    result = []
    i, j = n1, n2
    k = 0

    while i > 0 and j > 0:
        found_move = False

        # Check if current position came from a match
        if i > 0 and j > 0 and k >= 0 and dp[i][j][k] > INF:
            # Check if s1[i-1] == s2[j-1] transition works
            if i > 0 and j > 0 and s1[i-1] == s2[j-1]:
                nk = next_state(0, s1[i-1]) if k == 0 else 0
                nk_created = next_state(k, s1[i-1])
                prev_val = dp[i-1][j-1][k] if k < n3 else INF
                if prev_val > INF and nk_created < n3 and prev_val + 1 == dp[i][j][nk_created]:
                    result.append(s1[i-1])
                    i -= 1
                    j -= 1
                    k = nk_created
                    found_move = True

        # Try other moves if match didn't work
        if not found_move:
            if i > 0 and j > 0 and dp[i-1][j][k] > dp[i][j][k]:
                i -= 1
                k = next_state(k, s1[i]) if k < n3 and i > 0 else 0
            elif j > 0:
                j -= 1
        elif i > 0:
            i -= 1
        elif j > 0:
            j -= 1

    result.reverse()
    return "".join(result)


