                idx = parts[1]
                queries.append(('remove', idx, None, i))
            elif t == 3:
                q = parts[1]
                queries.append(('query', q, None, i))

        if not queries:
            return ''

        result_lines = []
        active = {}  # query_number -> (x, y)

        for q_type, arg1, arg2, q_idx in queries:
            if q_type == 'add':
                a, b = arg1, arg2
                active[q_idx] = (a, b)
            elif q_type == 'remove':
                if arg1 in active:
                    del active[arg1]
            elif q_type == 'query':
