from collections import deque

def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)

    def bfs(start):
        dist = [float('inf')] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] > dist[u] + 1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    dist = [bfs(i) for i in range(n + 1)]

    max_total = -1
    best = (1, 2, 3, 4)

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if dist[i][j] == float('inf'):
                continue
            for k in range(j + 1, n + 1):
                if dist[j][k] == float('inf'):
                    continue
                for l in range(k + 1, n + 1):
                    if dist[k][l] == float('inf'):
                        continue
                    total = dist[i][j] + dist[j][k] + dist[k][l]
                    if total > max_total:
                        max_total = total
                        best = (i, j, k, l)

    result = list(best)
    max_dist = len(result) - 1
    for i in range(len(result) - 1):
        result.append(result[max_dist] if max_dist == 0 else result[max_dist - 1])
        max_dist += 1
    return ' '.join(map(str, result))
