def solution(input_data):
    """
    Solve the interactive grid traversal problem.

    Args:
        input_data: String containing the full interactive protocol
                   Format: "n m [swapLR swapUD] [grid rows] [position readings]..."

    Returns:
        String containing the sequence of button presses
    """
    lines = input_data.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    # Parse swap flags from line 1
    swap_lines = ["0", "0"]
    if len(lines) > 1:
        parts = lines[1].split()
        if len(parts) >= 2:
            swapLR = int(parts[0])
            swapUD = int(parts[1])
        elif len(parts) == 1:
            swapLR = int(parts[0])
            swapUD = 0
        else:
            swapLR = 0
            swapUD = 0
    else:
        swapLR = 0
        swapUD = 0

    # Get actual direction mappings with swaps
    # Normal direction: U=(-1,0), D=(1,0), L=(0,-1), R=(0,1)
    normal_dr = {'U': -1, 'D': 1}
    normal_dc = {'L': -1, 'R': 1}

    def get_dr(move):
        dr = normal_dr[move]
        if swapUD == 1 and move in ('U', 'D'):
            dr = -dr
        return dr

    def get_dc(move):
        dc = normal_dc[move]
        if swapLR == 1 and move in ('L', 'R'):
            dc = -dc
        return dc

    # Build grid from input
    grid = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid.append(lines[i])

    # Find finish position
    finish_pos = None
    for r in range(n):
        if r < len(grid):
            for c in range(m):
                if c < len(grid[r]) and grid[r][c] == 'F':
                    finish_pos = (r, c)
                    break
        if finish_pos:
            break

    if not finish_pos:
        return ""

    # BFS to find shortest path
    from collections import deque

    start_pos = (0, 0)
    visited = {start_pos}
    parent = {start_pos: (None, None)}
    queue = deque([start_pos])

    while queue:
        r, c = queue.popleft()

        if (r, c) == finish_pos:
            break

        for move in ['U', 'D', 'L', 'R']:
            dr = get_dr(move)
            dc = get_dc(move)
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m:
                if nr < len(grid) and nc < len(grid[nr]):
                    if grid[nr][nc] != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        parent[(nr, nc)] = (r, c, move)
                        queue.append((nr, nc))

    # Reconstruct path
    if (0, 0) == finish_pos:
        return ""

    path = []
    curr = finish_pos
    while curr != start_pos:
        prev, move = parent[curr]
        path.append(move)
        curr = prev
    path.reverse()

    return '\n'.join(path) + '\n' if path else ""
