    # True = first operation is addition, False = first operation is subtraction
    starts_with_add = True

    while len(a) > 1:
        new_a = []
        # Apply operations alternating within the row
        for i in range(len(a) - 1):
            if i % 2 == 0:
                if starts_with_add:
                    # Even index: use add if start is add, sub if start is sub
                    new_a.append((a[i] + a[i+1]) % MOD)
                else:
                    # Even index: use sub if start is sub (negative means already sub)
                    new_a.append((a[i] - a[i+1]) % MOD)
            else:
                if starts_with_add:
                    # Odd index: use sub if start is add
                    new_a.append((a[i] - a[i+1]) % MOD)
                else:
                    # Odd index: use add if start is sub
                    new_a.append((a[i] + a[i+1]) % MOD)

        a = new_a

        # Determine if the last operation (at the last position of old row) was addition
        # If starts_with_add: last operation at even index is add, at odd index is sub
        # If not starts_with_add: last operation at even index is sub, at odd index is add
        old_len = len(a) + 1  # The length before reduction
        last_idx = last_idx = old_len - 1 - 1  # Last index in old array, which was old_len - 2
        last_idx = old_len - 2

        if starts_with_add:
            last_was_add = last_idx % 2 == 0  # i is even → add
        else:
            last_was_add = last_idx % 2 == 1  # i is odd → add

        # Next row starts with the same operation that previous row ended with
        starts_with_add = last_was_add

    # Return the result modulo MOD, ensuring non-negative
    result = a[0] % MOD
    return str(result) if result >= 0 else str(result + MOD)
