    min_time = float('inf')
    best_pos = None

    def dist3(p1, p2):
        return math.sqrt(sum((p1[i] - p2[i])**2 for i in range(3)))

    def snitch_at_time(t, A, B, seg_len, seg_time):
        if t <= 0:
            return list(A)
        if t >= seg_time:
            return list(B)
        ratio = t / seg_time
        return [A[i] + ratio * (B[i] - A[i]) for i in range(3)]

    def HP_reaches(t):
        sp = snitch_at_time(t, A, B, seg_len, seg_time)
        return dist3(H, sp) <= vp * t + 1e-9

    for i in range(n):
        A = points[i]
        B = points[i+1]
        seg_len = dist3(A, B)
        if seg_len < 1e-12:
            continue
        seg_time = seg_len / vs

        # Binary search on time
        lo, hi = 0.0, seg_time
        found = False
        for _ in range(100):
            mid = (lo + hi) / 2
            if HP_reaches(mid):
                found = True
                hi = mid
            else:
                lo = mid

        if found:
            t = (lo + hi) / 2
            if t < min_time - 1e-9:
                min_time = t
                best_pos = snitch_at_time(t, A, B, seg_len, seg_time)

    # Check if HP starts at the first vertex
